#include <cstdint>
#include <iostream>
#include <string>

// The solution file defines these identically; the layout must match.
constexpr unsigned kRingCapacity = 8;

struct RingBuffer
{
    std::uint8_t data[kRingCapacity];
    std::uint8_t head;
    std::uint8_t tail;
    std::uint8_t count;
};

void Init(RingBuffer& rb);
bool Push(RingBuffer& rb, std::uint8_t value);
bool Pop(RingBuffer& rb, std::uint8_t& value);

int main()
{
    int n;
    while (std::cin >> n)
    {
        RingBuffer rb;
        // Poison the struct so an Init that forgets a field is visible.
        rb.head = 5;
        rb.tail = 3;
        rb.count = 7;
        Init(rb);
        for (int i = 0; i < n; i++)
        {
            std::string op;
            std::cin >> op;
            if (op == "push")
            {
                int v;
                std::cin >> v;
                std::cout << (Push(rb, static_cast<std::uint8_t>(v)) ? "+" : "!");
            }
            else
            {
                std::uint8_t out = 0xEE;
                if (Pop(rb, out))
                {
                    std::cout << static_cast<int>(out);
                }
                else
                {
                    std::cout << "E" << (out == 0xEE ? "" : "?");
                }
            }
            std::cout << (i + 1 < n ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}

