"""Random push/pop sequences, biased to fill the buffer and wrap it several
times."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    ops = []
    bias = rng.choice([0.4, 0.6, 0.8])
    for _ in range(rng.randint(12, 30)):
        if rng.random() < bias:
            ops.append("push %d" % rng.randint(0, 255))
        else:
            ops.append("pop")
    return {"name": "%d operations, push bias %.1f #%d" % (len(ops), bias, index),
            "stdin": "%d\n%s\n" % (len(ops), "\n".join(ops))}
